import React from 'react';
import { Platform, Text, View, Button, ScrollView } from 'react-native';
import Duty from '../duty/Duty';
import DateTimePickerModal from 'react-native-modal-datetime-picker';

// Import the date and time picker components for web
import { DatePicker, TimePicker } from '@material-ui/pickers';

interface EndDutyModalProps {
  duty: Duty;
  updateDutyDetails: (updatedDuty: Duty) => void;
  closeModal: () => void;
}

interface EndDutyModalState {
  dutyStartDate: Date;
  dutyStartTime: Date;
  dutyEndDate: Date;
  dutyEndTime: Date;
  isOSDAApplicable: boolean;
  isRRAApplicable: boolean;
}

class EndDutyModal extends React.Component<EndDutyModalProps, EndDutyModalState> {
  state: EndDutyModalState = {
    dutyStartDate: new Date(),
    dutyStartTime: new Date(),
    dutyEndDate: new Date(),
    dutyEndTime: new Date(),
    isOSDAApplicable: false,
    isRRAApplicable: false,
  };

  handleEndDuty = () => {
    const { duty, updateDutyDetails } = this.props;
    const { dutyStartDate, dutyStartTime, dutyEndDate, dutyEndTime, isOSDAApplicable, isRRAApplicable } = this.state;

    const signInDateTime = new Date(dutyStartDate.getFullYear(), dutyStartDate.getMonth(), dutyStartDate.getDate(), dutyStartTime.getHours(), dutyStartTime.getMinutes());
    const signOffDateTime = new Date(dutyEndDate.getFullYear(), dutyEndDate.getMonth(), dutyEndDate.getDate(), dutyEndTime.getHours(), dutyEndTime.getMinutes());

    const updatedDuty = new Duty(duty.id, duty.trips);
    updatedDuty.setSignInAndSignOff(signInDateTime, signOffDateTime);
    updatedDuty.isOSDA = isOSDAApplicable;
    updatedDuty.isRRA = isRRAApplicable;

    updateDutyDetails(updatedDuty);
  };

  handleStartDateChange = (date: Date | null) => {
    if (date) {
      this.setState({ dutyStartDate: date });
    }
  };

  handleStartTimeChange = (time: Date | null) => {
    if (time) {
      this.setState({ dutyStartTime: time });
    }
  };

  handleEndDateChange = (date: Date | null) => {
    if (date) {
      this.setState({ dutyEndDate: date });
    }
  };

  handleEndTimeChange = (time: Date | null) => {
    if (time) {
      this.setState({ dutyEndTime: time });
    }
  };

  render() {
    const { closeModal } = this.props;
    const { dutyStartDate, dutyStartTime, dutyEndDate, dutyEndTime, isOSDAApplicable, isRRAApplicable } = this.state;

    return (
      <View style={{ padding: 20 }}>
        <ScrollView>
          <Text style={{ fontSize: 24, marginBottom: 20 }}>End Duty</Text>
          {Platform.OS === 'web' ? (
            <>
              <View>
                <Text>Duty Start Date:</Text>
                <DatePicker
                  value={dutyStartDate}
                  onChange={this.handleStartDateChange}
                  animateYearScrolling
                />
              </View>
              <View>
                <Text>Duty Start Time:</Text>
                <TimePicker
                  value={dutyStartTime}
                  onChange={this.handleStartTimeChange}
                />
              </View>
              <View>
                <Text>Duty End Date:</Text>
                <DatePicker
                  value={dutyEndDate}
                  onChange={this.handleEndDateChange}
                  animateYearScrolling
                />
              </View>
              <View>
                <Text>Duty End Time:</Text>
                <TimePicker
                  value={dutyEndTime}
                  onChange={this.handleEndTimeChange}
                />
              </View>
            </>
          ) : (
            <>
              <View>
                <Text>Duty Start Date:</Text>
                <Button title={dutyStartDate.toDateString()} onPress={this.showStartDatePicker} />
                <DateTimePickerModal
                  isVisible={isStartDatePickerVisible}
                  mode="date"
                  onConfirm={this.handleStartDateConfirm}
                  onCancel={this.hideStartDatePicker}
                />
              </View>
              <View>
                <Text>Duty Start Time:</Text>
                <Button title={dutyStartTime.toLocaleTimeString()} onPress={this.showStartTimePicker} />
                <DateTimePickerModal
                  isVisible={isStartTimePickerVisible}
                  mode="time"
                  onConfirm={this.handleStartTimeConfirm}
                  onCancel={this.hideStartTimePicker}
                />
              </View>
              <View>
                <Text>Duty End Date:</Text>
                <Button title={dutyEndDate.toDateString()} onPress={this.showEndDatePicker} />
                <DateTimePickerModal
                  isVisible={isEndDatePickerVisible}
                  mode="date"
                  onConfirm={this.handleEndDateConfirm}
                  onCancel={this.hideEndDatePicker}
                />
              </View>
              <View>
                <Text>Duty End Time:</Text>
                <Button title={dutyEndTime.toLocaleTimeString()} onPress={this.showEndTimePicker} />
                <DateTimePickerModal
                  isVisible={isEndTimePickerVisible}
                  mode="time"
                  onConfirm={this.handleEndTimeConfirm}
                  onCancel={this.hideEndTimePicker}
                />
              </View>
            </>
          )}
          <View style={{ flexDirection: 'row', alignItems: 'center', marginBottom: 20 }}>
            <Text>Is OSDA Applicable:</Text>
            <Button
              title={isOSDAApplicable ? "Yes" : "No"}
              onPress={() => this.setState({ isOSDAApplicable: !isOSDAApplicable })}
            />
          </View>
          <View style={{ flexDirection: 'row', alignItems: 'center', marginBottom: 20 }}>
            <Text>Is RRA Applicable:</Text>
            <Button
              title={isRRAApplicable ? "Yes" : "No"}
              onPress={() => this.setState({ isRRAApplicable: !isRRAApplicable })}
            />
          </View>
          <Button title="End Duty" onPress={this.handleEndDuty} />
          <Button title="Cancel" onPress={closeModal} />
        </ScrollView>
      </View>
    );
  }
}

export default EndDutyModal;
